import numpy as np
from scipy.spatial.transform import Rotation
from scipy.optimize import least_squares
# ViperX 300s link dimensions from the manufacturer's URDF.
LINKS=np.array([[0,0,.079],[0,0,.04805],[.05955,0,.3],[.2,0,0],[.1,0,0],[.069744,0,0]])
AXES=np.array([[0,0,1],[0,1,0],[0,1,0],[1,0,0],[0,1,0],[1,0,0]])
def chain(q):
    T=np.eye(4); frames=[]
    for p,a,t in zip(LINKS,AXES,q):
        A=np.eye(4); A[:3,3]=p; A[:3,:3]=Rotation.from_rotvec(a*t).as_matrix(); T=T@A; frames.append(T.copy())
    return frames
class HardwareArm:
    def __init__(self,name,base): self.name=name; self.base=np.array(base)
    def fk(self,q): return self.base@chain(q)[-1]
    def frames(self,q): return [self.base@T for T in chain(q)]
    def solve(self,p,R=None,offset=None,start=None):
        if offset is None: offset=np.array([.11,0,0])
        if start is None: start=np.array([0,-.5,1.2,0,-.5,0])
        def residual(q):
            T=self.fk(q); err=(T[:3,3]+T[:3,:3]@offset-np.array(p))*5
            if R is not None: err=np.r_[err,Rotation.from_matrix(np.array(R).T@T[:3,:3]).as_rotvec()*.6]
            return err
        lo=np.array([-3.14158,-1.85005,-1.76278,-3.14158,-1.8675,-3.14158]); hi=np.array([3.14158,1.25664,1.6057,3.14158,2.23402,3.14158])
        sol=least_squares(residual,start,bounds=(lo,hi),xtol=1e-11,ftol=1e-11,gtol=1e-11,max_nfev=1000)
        print(self.name,'IK error',np.linalg.norm(residual(sol.x)),'q',np.round(sol.x,5))
        return sol.x
